import{z as d,x as n,o as E,c as s,q as o,j as r,D as e,d as l,s as i,S as A}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"循环不变量外提","description":"","frontmatter":{"title":"循环不变量外提","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/licm.md","filePath":"cs/licm.md","lastUpdated":1791413859000}'),p={name:"cs/licm.md"};function c(h,a,B,_,m,C){const t=n("Mermaid");return E(),s("div",null,[a[2]||(a[2]=o('<h1 id="循环不变量外提" tabindex="-1">循环不变量外提 <a class="header-anchor" href="#循环不变量外提" aria-label="Permalink to &quot;循环不变量外提&quot;">​</a></h1><div class="epigraph"><p>若计算在循环每一圈结果相同，且外提安全，就搬到前置头执行一次。安全包括异常、别名与执行频率。</p><footer>—— 据 Allen and Cocke, A Catalogue of Optimizing Transformations；龙书 9.5；Muchnick 整理</footer></div><p>前课<a href="/cs/dce-adce">DCE</a>删死的。缺口是<strong>活但不随迭代变</strong>的表达式：<code>t = n*4</code> 在 <code>for</code> 里。LICM：识别循环、找不变、外提到 preheader。主干点过循环；自然循环识别后课正式收。本课假定可识别自然循环与前置头。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>不变：操作数在循环外定义，或本身不变。外提：preheader 支配所有入口。缺口是<strong>安全性</strong>：load 在循环里可能不执行（保护在 <code>if</code> 后），外提会引入新的陷阱或多执行。必须：计算在原循环每次入口都必执行，或语言允许投机（无副作用）。</p><p>与 CSE：先 LICM 再 GVN，或不变表达式当循环外公共值。</p><h3 id="外提不是循环展开" tabindex="-1">外提不是循环展开 <a class="header-anchor" href="#外提不是循环展开" aria-label="Permalink to &quot;外提不是循环展开&quot;">​</a></h3><p>展开复制体；LICM 减少每圈工作。二者后课可组合。</p><p><span class="marginnote">Allen–Cocke。龙书循环优化。Appel 有短节。本课不写完整别名；load 外提默认要「必执行且无别名写」。</span></p><p><span class="marginnote">「前置头（preheader）」就是在循环入口外专门开辟一个空基本块的手段：外提的指令放这里，循环的所有入口都先经过它，计算因此每进循环只跑一次，而不是每圈一次。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对循环嵌套从内到外。SSA：名的 def 在循环外则不变。有循环内 def 则否。条件外提：用控制依赖或「循环内必经」分析。</p>',12)),(E(),r(A,null,{default:e(()=>[i(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20L%5B%22%E8%87%AA%E7%84%B6%E5%BE%AA%E7%8E%AF%22%5D%20--%3E%20INV%5B%22%E4%B8%8D%E5%8F%98%E8%AE%A1%E7%AE%97%22%5D%0A%20%20INV%20--%3E%20SAFE%5B%22%E5%BF%85%E6%89%A7%E8%A1%8C%20%2F%20%E6%97%A0%E5%89%AF%E4%BD%9C%E7%94%A8%22%5D%0A%20%20SAFE%20--%3E%20PH%5B%22%E5%89%8D%E7%BD%AE%E5%A4%B4%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=o('<p>寄存器压力：外提过多拉长存活，可能更差——启发后课与寄存器分配交互。</p><p><span class="marginnote">数字实例：<code>t = n*4</code> 在跑 100 万圈的循环里，不外提就乘 100 万次；外提到前置头后只乘 1 次，其余 999999 次凭空消失。热循环里一行不变代码的省略，往往就是 LICM 最直观的收益。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p><code>volatile</code> 与原子不外提。调用：须证明纯。整数溢出：C 对有符号溢出是 UB，外提可能改变「是否溢出」的路径——UB 课再钉。</p><p>不要外提可能别名的 load 跨过 store。</p><p><span class="marginnote">常见误区：初学者以为「结果不变」就能外提。若该计算在循环里受 <code>if</code> 保护、可能一次都不执行，外提后却每次必跑——除零、空指针解引用这类陷阱就从「可能不发生」变成「必然发生」，这正是必执行检查存在的原因。</span></p>',6)),(E(),r(A,null,{default:e(()=>[i(t,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20E%5B%22%E5%BE%AA%E7%8E%AF%E5%86%85%E5%80%99%E9%80%89%E8%AE%A1%E7%AE%97%22%5D%20--%3E%20Q1%7B%22%E6%93%8D%E4%BD%9C%E6%95%B0%E9%9A%8F%E8%BF%AD%E4%BB%A3%E5%8F%98%EF%BC%9F%22%7D%0A%20%20Q1%20--%20%22%E5%8F%98%22%20--%3E%20KEEP%5B%22%E7%95%99%E5%9C%A8%E5%BE%AA%E7%8E%AF%E5%86%85%22%5D%0A%20%20Q1%20--%20%22%E4%B8%8D%E5%8F%98%22%20--%3E%20Q2%7B%22%E6%AF%8F%E6%AC%A1%E5%85%A5%E5%8F%A3%E5%BF%85%E6%89%A7%E8%A1%8C%20%E6%88%96%E6%8A%95%E6%9C%BA%E5%AE%89%E5%85%A8%EF%BC%9F%22%7D%0A%20%20Q2%20--%20%22%E5%90%A6%22%20--%3E%20KEEP%0A%20%20Q2%20--%20%22%E6%98%AF%22%20--%3E%20Q3%7B%22load%20%E6%98%AF%E5%90%A6%E5%8F%AF%E8%83%BD%E5%88%AB%E5%90%8D%20store%EF%BC%9F%22%7D%0A%20%20Q3%20--%20%22%E5%8F%AF%E8%83%BD%22%20--%3E%20KEEP%0A%20%20Q3%20--%20%22%E4%B8%8D%E4%BC%9A%22%20--%3E%20HOIST%5B%22%E5%A4%96%E6%8F%90%E5%88%B0%E5%89%8D%E7%BD%AE%E5%A4%B4%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=o('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写强度削弱。后课默认：安全的不变计算进 preheader。下一课归纳变量与强度削弱：<code>i*4</code> 变成加法。</p><p>也不把 LICM 当多面体调度。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>LICM：不变且安全的计算搬到前置头。</li><li>安全 = 无新副作用/陷阱，通常要必执行。</li><li>与 SSA 支配、循环识别绑定。</li><li>出处：Allen and Cocke；Aho et al. 龙书；Muchnick。</li></ul>',5))])}const F=d(p,[["render",c]]);export{f as __pageData,F as default};
